import unittest
import mock
from mock import patch
from taf.ul.oam.selenium_coam.pages.panels.view import ViewPanel


class TestViewPanel(unittest.TestCase):
    @patch('taf.ul.oam.selenium_coam.common.common.CustomWebdriver')
    def setUp(self, mock_driver):
        mock_driver.return_value = mock.MagicMock()
        self.view_panel = ViewPanel()

    def test_show_detail_panel(self):
        xpath = "//somewhere"
        index = 0
        self.view_panel.click_and_wait_for_corresponding_element_visible = mock.Mock()

        self.view_panel.show_detail_panel(xpath)
        self.view_panel.click_and_wait_for_corresponding_element_visible.\
            assert_called_once_with(xpath, self.view_panel._DETAIL_PANEL_XPATH, index)
